def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except:
                return default
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_of(items, scorer, pick_min=True):
        best_item = None
        best_score = None
        for it in items or []:
            try:
                s = scorer(it)
            except:
                continue
            if best_item is None:
                best_item, best_score = it, s
            else:
                if pick_min and s < best_score:
                    best_item, best_score = it, s
                elif not pick_min and s > best_score:
                    best_item, best_score = it, s
        return best_item

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position"))
    opp_pos = pos(observation.get("opponent_position"), self_pos)
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        target = best_of(corners, lambda c: manhattan(c, opp_pos), pick_min=False)
        if target is None:
            return [0, 0]
        return step_toward(self_pos, target)

    if env == "territory_control":
        own = observation.get("own_territory") or observation.get("claimed_cells") or []
        frontier = observation.get("frontier_cells") or observation.get("unclaimed_cells") or []
        enemy = observation.get("opponent_territory") or []
        targets = frontier or enemy or own
        target = best_of(targets, lambda c: manhattan(pos(c, self_pos), self_pos), pick_min=True)
        if target is not None:
            return step_toward(self_pos, pos(target, self_pos))
        if enemy:
            target = best_of(enemy, lambda c: manhattan(pos(c, self_pos), opp_pos), pick_min=True)
            if target is not None:
                return step_toward(self_pos, pos(target, self_pos))
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        target = best_of(resources, lambda c: manhattan(pos(c, self_pos), self_pos), pick_min=True)
        if target is not None:
            return step_toward(self_pos, pos(target, self_pos))

    # Deny or pressure the opponent if no obvious resource target exists.
    if observation.get("resource_positions") is None and observation.get("resources") is None:
        return [0, 0] if self_pos == opp_pos else step_toward(self_pos, opp_pos)

    # Fallback: move toward opponent but avoid doing nothing when far away.
    return step_toward(self_pos, opp_pos)

